def tokenize_naive(src):
    stats = {"skip_calls": 0, "chars_examined": 0}
    n = len(src)
    def skip_ws(pos):
        stats["skip_calls"] += 1
        while pos < n:
            stats["chars_examined"] += 1
            if src[pos] == " ":
                pos += 1
            else:
                break
        return pos
    tokens = []
    i = 0
    while True:
        # a lookahead-heavy parser peeks several times before consuming
        start = skip_ws(skip_ws(skip_ws(i)))
        if start >= n:
            break
        j = start
        if src[j].isalpha():
            while j < n and src[j].isalnum():
                stats["chars_examined"] += 1
                j += 1
        else:
            stats["chars_examined"] += 1
            j += 1
        tokens.append(src[start:j])
        i = j
    return tokens, stats

def tokenize_single_pass(src):
    stats = {"chars_examined": 0}
    tokens = []
    i, n = 0, len(src)
    while i < n:
        ch = src[i]
        stats["chars_examined"] += 1
        i += 1
        if ch == " ":
            continue
        if ch.isalpha():
            j = i
            while j < n and src[j].isalnum():
                stats["chars_examined"] += 1
                j += 1
            tokens.append(src[i - 1:j])
            i = j
        else:
            tokens.append(ch)
    return tokens, stats

