def makespan_occupancy(durations, workers):
    free_at = [0] * workers
    for d in durations:
        w = min(range(workers), key=lambda i: free_at[i])
        free_at[w] += d
    return max(free_at)

def makespan_core_capped(units, workers, cores):
    parallel = min(workers, cores)
    remaining = list(units)
    ticks = 0
    while any(remaining):
        advanced = 0
        for i in range(len(remaining)):
            if remaining[i] > 0 and advanced < parallel:
                remaining[i] -= 1
                advanced += 1
        ticks += 1
    return ticks

