class FakeTransport:
    def __init__(self, data):
        self.data = data
        self.pos = 0
        self.calls = 0
    def recv(self, n):
        self.calls += 1
        chunk = self.data[self.pos:self.pos + n]
        self.pos += len(chunk)
        return chunk

DATA = bytes(8000)

def read_bytewise(t, n):
    out = bytearray()
    while len(out) < n:
        out += t.recv(1)
    return bytes(out)

def read_buffered(t, n, bufsize=4096):
    out = bytearray()
    while len(out) < n:
        out += t.recv(min(bufsize, n - len(out)))
    return bytes(out)

