DOWN_UNTIL = 30

def attempts_no_backoff(callers=3):
    total = 0
    per_tick = {}
    for c in range(callers):
        t = 0
        while True:
            total += 1
            per_tick[t] = per_tick.get(t, 0) + 1
            if t >= DOWN_UNTIL:
                break
            t += 1
    return total, per_tick

def attempts_backoff(callers=3):
    total = 0
    attempt_ticks = []
    for c in range(callers):
        t = c
        gap = 5
        while True:
            total += 1
            attempt_ticks.append(t)
            if t >= DOWN_UNTIL:
                break
            t += gap
            gap *= 2
    return total, sorted(attempt_ticks)

