class LazySearcher:
    def __init__(self, rows):
        self.rows = rows
        self.index = None
        self.ops = 0
    def _build(self):
        self.index = {}
        for k, v in self.rows:
            self.index[k] = v
            self.ops += 1
    def find(self, key):
        if self.index is None:
            self._build()
        self.ops += 1
        return self.index[key]

