import random

def dedup_oracle(items):
    out = []
    for x in items:
        if x not in out:
            out.append(x)
    return out

def dedup_corrected(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

